const cities={深圳:[22.58,113.99],北京:[39.91,116.4],上海:[31.23,121.47],成都:[30.66,104.07],广州:[23.13,113.26],杭州:[30.27,120.15],重庆:[29.56,106.55],武汉:[30.59,114.3],南京:[32.06,118.8],西安:[34.34,108.94],长沙:[28.23,112.94],郑州:[34.75,113.62],天津:[39.13,117.2],苏州:[31.3,120.58],厦门:[24.48,118.09],福州:[26.07,119.3],昆明:[25.04,102.72],贵阳:[26.65,106.63],南宁:[22.82,108.32],海口:[20.04,110.2],三亚:[18.25,109.51],济南:[36.65,117.12],青岛:[36.07,120.38],沈阳:[41.8,123.43],大连:[38.91,121.61],哈尔滨:[45.8,126.53],长春:[43.82,125.32],合肥:[31.82,117.23],南昌:[28.68,115.86],太原:[37.87,112.55],石家庄:[38.04,114.51],兰州:[36.06,103.83],西宁:[36.62,101.78],银川:[38.49,106.23],呼和浩特:[40.84,111.75],乌鲁木齐:[43.83,87.62],拉萨:[29.65,91.14],香港:[22.32,114.17],澳门:[22.2,113.54],台北:[25.03,121.56]};
const definitions={restricted:{label:'禁飞示例',color:'#cc656b',name:'机场周边 · 演示区',description:'用于展示禁止飞行区域的界面与边界交互。此范围为虚构示意，不对应机场净空保护边界。'},limited:{label:'限高示例',color:'#d1a041',name:'城市北部 · 演示区',description:'用于展示限高区域的信息样式。示例高度不代表当地的实际飞行限制。'},notice:{label:'提示示例',color:'#699bb8',name:'东部片区 · 演示区',description:'用于展示需要关注额外通告的区域。未接入当地临时管制或活动通告。'}};
let currentCity='深圳',filter='all',map,group,selected=null,activeLayers=new Set(Object.keys(definitions)),records=[],locationMarker,timer;
const $=s=>document.querySelector(s);const $$=s=>document.querySelectorAll(s);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,5000)}
function makeRecords(city){const [lat,lng]=cities[city];return Object.entries(definitions).map(([type,d],i)=>({...d,type,id:city+type,city,center:[lat+[-.025,.09,.015][i],lng+[-.13,.01,.12][i]],radius:[4300,5300,3600][i]}))}
function select(record){selected=record.id;renderList();if(map)map.flyTo(record.center,12,{duration:.7});const node=$('#detail');node.hidden=false;node.innerHTML=`<button class="detail-close" aria-label="关闭详情">×</button><span class="detail-badge">${record.label} · 虚构边界</span><h3>${record.name}</h3><p>${record.description}</p><dl><dt>所在城市</dt><dd>${record.city}</dd><dt>区域数据</dt><dd>原型演示 / 未经核验</dd><dt>飞行高度</dt><dd>${record.type==='limited'?'示例值 60 米（非实际限制）':'未提供实际限制'}</dd></dl><p class="detail-note">不能据此判断是否可飞。请核验官方空域信息及当地通告。</p>`;node.querySelector('button').onclick=()=>{node.hidden=true;selected=null;renderList()}}
function visible(r){return (filter==='all'||r.type===filter)&&activeLayers.has(r.type)}
function renderList(){const list=records.filter(visible);$('#area-title').textContent=currentCity==='全国'?'全国 · 示例城市':currentCity+' · 示例区域';$('#count').textContent=list.length+' 个';$('#region-list').innerHTML='';if(!list.length){$('#region-list').innerHTML='<p class="empty">当前没有显示的示例区域。<br>可切换筛选或开启图层查看。</p>';return}list.forEach(r=>{const b=document.createElement('button');b.className='region-card'+(selected===r.id?' selected':'');b.innerHTML=`<span class="region-card-top"><i class="dot ${r.type}"></i><strong>${currentCity==='全国'?r.city+' · ':''}${r.name}</strong><span class="arrow">↗</span></span><p>${r.label} <span>·</span> 虚构示意边界</p>`;b.onclick=()=>select(r);$('#region-list').appendChild(b)})}
function renderMap(){if(!map)return;group.clearLayers();records.filter(visible).forEach(r=>{L.circle(r.center,{radius:r.radius,color:r.color,weight:1.5,fillColor:r.color,fillOpacity:.2,dashArray:r.type==='notice'?'5 5':undefined}).addTo(group).on('click',()=>select(r));L.circleMarker(r.center,{radius:5,color:'#fff',weight:2,fillColor:r.color,fillOpacity:1}).addTo(group).on('click',()=>select(r))});if(selected&&!records.filter(visible).some(r=>r.id===selected)){$('#detail').hidden=true;selected=null}}
function city(name){currentCity=name;records=makeRecords(name);selected=null;$('#detail').hidden=true;$('#map-city').textContent=name+'市';$('#search-results').innerHTML='';$('#search').value='';renderList();renderMap();if(map)map.flyTo(cities[name],11,{duration:.8})}
function national(){currentCity='全国';records=['深圳','北京','上海','成都','广州','杭州','武汉','西安'].flatMap(makeRecords);selected=null;$('#detail').hidden=true;$('#map-city').textContent='全国概览';renderList();renderMap();if(map)map.flyTo([35.5,104.2],4,{duration:1})}
function search(){const query=$('#search').value.trim().replace(/市$/,'');const container=$('#search-results');container.innerHTML='';if(!query)return;const matches=Object.keys(cities).filter(c=>c.includes(query));const zones=records.filter(r=>(r.name+r.city+r.label).includes(query));if(!matches.length&&!zones.length){container.innerHTML='<p>暂未收录该地点。试试“深圳”“上海”，或拖动地图浏览。</p>';return}matches.slice(0,6).forEach(c=>{const b=document.createElement('button');b.textContent=c+' · 定位城市';b.onclick=()=>city(c);container.appendChild(b)});zones.slice(0,4).forEach(r=>{const b=document.createElement('button');b.textContent=r.city+' · '+r.name;b.onclick=()=>{select(r);container.innerHTML=''};container.appendChild(b)})}
$('#search').addEventListener('input',search);$('#search-form').onsubmit=e=>{e.preventDefault();search();const first=$('#search-results button');if(first)first.click()};$$('[data-city]').forEach(b=>b.onclick=()=>city(b.dataset.city));$('#national').onclick=national;
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderList();renderMap()});$$('[data-layer]').forEach(input=>input.onchange=()=>{input.checked?activeLayers.add(input.dataset.layer):activeLayers.delete(input.dataset.layer);renderList();renderMap()});
$('#zoom-in').onclick=()=>map?.zoomIn();$('#zoom-out').onclick=()=>map?.zoomOut();$('#reset').onclick=()=>currentCity==='全国'?national():city(currentCity);
$('#locate').onclick=()=>{if(!map)return toast('地图尚未加载，请刷新后重试。');if(!navigator.geolocation)return toast('当前浏览器不支持定位，请搜索城市。');toast('正在获取位置，请允许浏览器定位…');navigator.geolocation.getCurrentPosition(p=>{const point=[p.coords.latitude,p.coords.longitude];if(locationMarker)map.removeLayer(locationMarker);locationMarker=L.circleMarker(point,{color:'#fff',weight:3,fillColor:'#307cc2',fillOpacity:1,radius:8}).addTo(map).bindTooltip('我的位置');map.flyTo(point,13);toast('已定位。此处空域数据尚未核验。')},()=>toast('未能获取位置，请检查定位权限或搜索城市。'),{timeout:10000,enableHighAccuracy:false})};
const dialog=$('#info-dialog');$('#help').onclick=$('#data-info').onclick=()=>dialog.showModal();$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
if(window.L){map=L.map('map',{zoomControl:false,minZoom:3,maxZoom:18}).setView(cities.深圳,11);const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(map);let failures=0;tiles.on('tileerror',()=>{if(++failures===4)toast('底图暂时无法加载，请检查网络。彩色区域仅为演示。')});group=L.layerGroup().addTo(map);L.control.scale({position:'bottomleft',imperial:false}).addTo(map)}else{toast('地图组件加载失败，请检查网络并刷新。城市和区域列表仍可使用。');$('#map').innerHTML='<div style="padding:140px 30px;color:#53665a;text-align:center">地图暂时无法加载<br><small>请检查网络连接后刷新页面</small></div>'}
city('深圳');
